{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 조례상 노외주차장 주차전용건축물의 해당 부분 최대 높이(m)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "대지가 너비 24m 도로에 접하므로 제5조제1항제4호나목이 적용된다. 해당 부분으로부터 도로 반대편 경계선까지 수평거리가 30m이므로 배율은 30×(36/24)=45배이다. 배율이 1.8배 미만이 아니므로 단서는 적용되지 않는다. 따라서 그 부분의 최대 높이는 30m×45=1,350m이다.",
          "b_ids": "주차장:제5조제1항제4호, 주차장:제5조제1항제4호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
